export type TStreamType = 'piped' | 'inherit'

export type TExecResult = {
	success: boolean
	notNeeded?: true
	stdout?: string
	stderr?: string
	infile?: string
	outfile?: string
}

// ---------------------------------------------------------------------------
// ASYNC

export const mkstr = (
		item: string | BufferSource
		): string => {

	return (
		  isString(item) ? stripAnsiCode(item)
		: isArray(item)  ? stripAnsiCode(item.join(''))
		:                  stripAnsiCode(decode(item))
		)
}

// ---------------------------------------------------------------------------
// ASYNC
// --- Four cases for stdout:
//        1. no callback, capture false
//           output goes directly to the console
//        2. callback defined
//           output goes to a callback function
//        3. capture is set
//           output is found in the result hash
//        4. callback defined and capture set
//           output both in result hash and goes to callback

type TExecInput = string | string[] | TIterator<string> | TAsyncIterator<string>
type TExecCallback = (str: string) => void

export const execCmd = async (
		cmdName: string,
		lArgs: string[] = [],
		hOptions: hash = {}
		): AutoPromise<TExecResult> => {

	type opt = {
		input: (TExecInput | undefined)
		callback: (TExecCallback | undefined)
		capture: boolean
		infile: (string | undefined)
		outfile: (string | undefined)
		}

	const {input, callback, capture, infile, outfile
			} = getOptions<opt>(hOptions, {
		input: undef,
		callback: undef,
		capture: false,
		infile: undef,
		outfile: undef
		})

	DBG(`execCmd: ${getCmdLine(cmdName, lArgs)}`)

	const pipeStdout = capture || anyDefined(callback, outfile)
	const pipeStdin  = anyDefined(input, infile)

	if (!pipeStdout && !pipeStdin) {
//		cmd := new Deno.Command cmdName, {
//			args: lArgs
//			stdin: 'inherit'
//			stdout: 'inherit'
//			}
//		child := cmd.spawn()
		const child = Deno.spawn(cmdName, lArgs)
		const status = await child.status
		return {success: status.success}
	}

//		code := hResult.code
//		success := hResult.success
//		stdout := decode(hResult.stdout)
//		stderr := decode(hResult.stderr)
//		return {success, stdout, stderr}

	const cmd: Deno.Command = new Deno.Command(cmdName, {
		args: lArgs,
		env: {DEFAULT_LOGGER: curLogLevel()},
		stdin:  pipeStdin  ? 'piped' : 'inherit',
		stdout: pipeStdout ? 'piped' : 'inherit',
		stderr: 'piped'
		})
	const child: Deno.ChildProcess = cmd.spawn()

	if (defined(infile)) {
		assert(notdefined(input), "Can't use both infile and input")
		const contents = await Deno.readTextFile(infile)
		const iter = allLinesIn(contents, {includeNL: true})
		ReadableStream.from(iter)
			.pipeThrough(new TextEncoderStream())
			.pipeTo(child.stdin)
	}
	else if (defined(input)) {
		// --- type of child.stdin is WritableStream<Uint8Array>
		if (isString(input)) {
			const iter = allLinesIn(input, {includeNL: true})
			ReadableStream.from(iter)
				.pipeThrough(new TextEncoderStream())
				.pipeTo(child.stdin)
		}
		else {
			ReadableStream.from(input)
				.pipeThrough(new TextEncoderStream())
				.pipeTo(child.stdin)
		}
	}

	// --- Create a WritableStream that output can be sent to
	// --- type of child.stdout is WritableStream<Uint8Array>

	let stdout: string = ''
	const f = defined(outfile) ? new CWritableFile(outfile) : undef
	const outStrm: WritableStream<string> = (
		(defined(callback)?
			new WritableStream<string>({
				async write(chunk) {
					callback(chunk)
					if (defined(f)) {
						await f.write(chunk)
					}
					if (capture) {
						stdout += chunk
					}
					return
				}
				})
		:
			new WritableStream<string>({
				async write(chunk) {
					stdout += chunk
					if (defined(f)) {
						await f.write(chunk)
					}
					return
				}
				}))
		)

	await (
		child.stdout
		  .pipeThrough(new TextDecoderStream())
		  .pipeTo(outStrm, {preventClose: true})
			)
	const status = await child.status
	return {
		success: status.success,
		stdout,
		stderr: await child.stderr.text(),
		...(infile && {infile}),
		...(outfile && {outfile})
		}
}

