export const isInstalled = (scriptName: string): boolean => {

	const homeDir = Deno.env.get("HOME") ?? Deno.env.get("USERPROFILE") ?? ""
	const ext = (Deno.build.os === "windows") ? ".cmd" : ""
	const path = `${homeDir}/.deno/bin/${scriptName}${ext}`
	return existsSync(path) && Deno.statSync(path).isFile
}

// ---------------------------------------------------------------------------

export const getCmdName = (
		path: string,
		hOptions: hash
		): string => {

	if (('name' in hOptions) && (typeof hOptions.name === 'string')) {
		return hOptions.name as string
	}
	else {
		return parsePath(path).stub.replaceAll('.', '_')
	}
}

